using System.Buffers.Binary;
using Compression.Registry;
using Reg = Compression.Registry.FormatRegistry;

namespace Compression.Lib;

/// <summary>
///   Identifies archive/compression formats by file extension and magic bytes.
///   Metadata is derived from the <see cref="FormatRegistry" /> at startup; only special
///   detection logic (PE/SFX scanning, LZMA heuristic, tar at offset 257) remains here.
/// </summary>
public static partial class FormatDetector {

  // Format enum is auto-generated by Compression.Registry.Generator
  // into FormatDetector.Format.g.cs — see SpecialFormats for Unknown/Sfx/Iso/Udf

  // ── Registry-backed lookup tables (built once on first use) ──────

  private static Dictionary<string, Format>? _idToFormat;
  private static Dictionary<Format, IFormatDescriptor>? _formatToDesc;
  private static Dictionary<string, Format>? _extToFormat; // single extensions
  private static Dictionary<string, List<Format>>? _extToFormats; // every claimant of an extension
  private static Dictionary<string, Format>? _compoundExtToFormat; // compound extensions
  private static Dictionary<Format, Format>? _compoundToStream; // TarGz → Gzip
  private static Dictionary<Format, Format>? _streamToCompound; // Gzip → TarGz

  /// <summary>
  ///   Bytes that must be read for the deepest registered magic signature to be
  ///   matchable. Derived from the registry rather than hardcoded so that adding a
  ///   descriptor with a deeper signature widens the probe automatically.
  ///   Filesystem superblocks sit well past the first sector (ext at 1024,
  ///   ISO 9660 at 32768, btrfs at 65536), so a fixed 512-byte read silently made
  ///   those formats undetectable by content.
  /// </summary>
  private static int _maxMagicExtent;

  /// <summary>Header size for the cheap first pass; covers the large majority of formats.</summary>
  private const int FastProbeBytes = 512;

  /// <summary>Upper bound on the deep probe, so a malformed descriptor cannot make us read a whole file.</summary>
  private const int MaxProbeBytes = 1 << 20;

  private static void EnsureRegistryMapped() {
    if (FormatDetector._idToFormat != null)
      return;

    FormatRegistration.EnsureInitialized();

    var idToFormat = new Dictionary<string, Format>(StringComparer.OrdinalIgnoreCase);
    var formatToDesc = new Dictionary<Format, IFormatDescriptor>();
    var extToFormat = new Dictionary<string, Format>(StringComparer.OrdinalIgnoreCase);
    var extToFormats = new Dictionary<string, List<Format>>(StringComparer.OrdinalIgnoreCase);
    var compoundExtToFormat = new Dictionary<string, Format>(StringComparer.OrdinalIgnoreCase);
    var compoundToStream = new Dictionary<Format, Format>();
    var streamToCompound = new Dictionary<Format, Format>();
    var maxMagicExtent = FastProbeBytes;

    foreach (var desc in Reg.All) {
      if (!Enum.TryParse<Format>(desc.Id, out var f)) 
        continue;

      idToFormat[desc.Id] = f;
      formatToDesc[f] = desc;

      foreach (var sig in desc.MagicSignatures) {
        var extent = sig.Offset + sig.Bytes.Length;
        if (extent > maxMagicExtent)
          maxMagicExtent = extent;
      }

      // Build extension → format maps
      foreach (var ext in desc.Extensions) {
        var key = ext.ToLowerInvariant();
        extToFormat.TryAdd(key, f);
        // Several descriptors routinely claim the same extension — .dmg by
        // Apple's disk image and by the HFS+ volume inside one, .po by ProDOS
        // images and gettext catalogues, .s5 by System V and HTFS. First claim
        // wins in the map above, which hands the file to a reader that cannot
        // read it; keeping every claimant lets the content settle it.
        if (!extToFormats.TryGetValue(key, out var claimants))
          extToFormats[key] = claimants = [];
        if (!claimants.Contains(f)) claimants.Add(f);
      }

      foreach (var ext in desc.CompoundExtensions)
        compoundExtToFormat.TryAdd(ext.ToLowerInvariant(), f);

      // Build compound tar ↔ stream maps
      if (desc.TarCompressionFormatId != null && idToFormat.TryGetValue(desc.TarCompressionFormatId, out var streamF)) {
        compoundToStream[f] = streamF;
        streamToCompound[streamF] = f;
      }
    }

    // Second pass for compound tar mappings (stream format may have been registered after compound)
    foreach (var desc in Reg.All) {
      if (desc.TarCompressionFormatId == null) 
        continue;

      if (!idToFormat.TryGetValue(desc.Id, out var cf)) 
        continue;

      if (!idToFormat.TryGetValue(desc.TarCompressionFormatId, out var sf)) 
        continue;

      compoundToStream.TryAdd(cf, sf);
      streamToCompound.TryAdd(sf, cf);
    }

    FormatDetector._idToFormat = idToFormat;
    FormatDetector._formatToDesc = formatToDesc;
    FormatDetector._extToFormat = extToFormat;
    FormatDetector._extToFormats = extToFormats;
    FormatDetector._compoundExtToFormat = compoundExtToFormat;
    FormatDetector._compoundToStream = compoundToStream;
    FormatDetector._streamToCompound = streamToCompound;
    FormatDetector._maxMagicExtent = Math.Min(maxMagicExtent, MaxProbeBytes);
  }

  /// <summary>
  ///   Identifies <paramref name="path"/> by content alone.
  ///   Probes the first <see cref="FastProbeBytes"/> bytes first — that settles the
  ///   large majority of formats — and only re-reads out to the deepest registered
  ///   signature when the cheap pass finds nothing.
  /// </summary>
  private static Format DetectByMagicFromFile(string path) {
    EnsureRegistryMapped();
    if (!File.Exists(path)) return Format.Unknown;

    try {
      using var fs = File.OpenRead(path);

      var fast = new byte[FastProbeBytes];
      var read = fs.ReadAtLeast(fast, fast.Length, throwOnEndOfStream: false);
      var byFast = DetectByMagic(fast.AsSpan(0, read));
      if (byFast != Format.Unknown) return byFast;

      // Nothing in the first sector. Widen to the deepest signature the registry
      // declares, but never past the end of the file.
      var deep = (int)Math.Min(FormatDetector._maxMagicExtent, fs.Length);
      if (deep <= read) return Format.Unknown;

      var buffer = new byte[deep];
      fs.Position = 0;
      read = fs.ReadAtLeast(buffer, deep, throwOnEndOfStream: false);
      return DetectByMagic(buffer.AsSpan(0, read));
    } catch (IOException) {
      return Format.Unknown;
    } catch (UnauthorizedAccessException) {
      return Format.Unknown;
    }
  }

  /// <summary>Get the descriptor for a format, or null if no descriptor exists (Sfx, Iso, Udf).</summary>
  private static IFormatDescriptor? GetDesc(Format f) {
    EnsureRegistryMapped();
    return FormatDetector._formatToDesc!.GetValueOrDefault(f);
  }

  // ── Category queries (derived from descriptor metadata) ──────────

  public static bool IsArchive(Format f) {
    if (f == Format.Sfx) 
      return true;

    var desc = GetDesc(f);
    return desc?.Category is FormatCategory.Archive or FormatCategory.CompoundTar or FormatCategory.DetectionOnly;
  }

  public static bool IsStreamFormat(Format f) {
    var desc = GetDesc(f);
    return desc?.Category is FormatCategory.Stream or FormatCategory.Wrapper;
  }

  public static bool IsCompoundTar(Format f) {
    var desc = GetDesc(f);
    return desc?.Category is FormatCategory.CompoundTar;
  }

  /// <summary>Returns the stream compression format wrapping a compound tar, or null if not compound.</summary>
  public static Format? GetTarCompression(Format f) {
    EnsureRegistryMapped();
    return FormatDetector._compoundToStream!.TryGetValue(f, out var s) ? s : null;
  }

  /// <summary>Returns the compound tar format for a given stream compression, or null.</summary>
  public static Format? GetCompoundTar(Format compression) {
    EnsureRegistryMapped();
    return FormatDetector._streamToCompound!.TryGetValue(compression, out var c) ? c : null;
  }

  // ── Extension detection ──────────────────────────────────────────

  public static Format DetectByExtension(string path) {
    EnsureRegistryMapped();
    var lower = path.ToLowerInvariant();

    // Compound extensions first (longest match, e.g. .tar.gz before .gz)
    foreach (var (ext, f) in FormatDetector._compoundExtToFormat!)
      if (lower.EndsWith(ext))
        return f;

    // Special cases not handled by registry
    var singleExt = Path.GetExtension(lower);
    if (singleExt == ".exe") 
      return DetectInstaller(path);

    if (singleExt is ".ar" or ".a" or ".deb") 
      return DetectArOrDeb(lower);

    if (lower.EndsWith(".sz_") || lower.EndsWith("._"))
      return Format.Szdd;

    // Generic disk-image extension claimed by many filesystems. The extension
    // carries no information here, so ask the content first — otherwise every
    // ext4/btrfs/ISO/NTFS image named ".img" is reported as FAT and routed to
    // the FAT reader, which rejects it. Only when the content says nothing do we
    // fall back to FAT as the most common writable target; that fallback is what
    // keeps Create working and stops the registry's first-claim-wins map from
    // routing ".img" to a niche read-only descriptor (Bfs, alphabetically).
    // Other ambiguous extensions (.bin, .dd, .raw) are NOT special-cased: .bin
    // belongs to BinCue (CD images), .dd is dd-image (raw), .raw is generic —
    // those correctly resolve via the registry to specific descriptors.
    if (singleExt == ".img") {
      var img = DetectByMagicFromFile(path);
      return img != Format.Unknown ? img : Format.Fat;
    }

    // The ".wad" extension is shared by Doom WADs (IWAD/PWAD magic, the "Wad"
    // descriptor) and Quake/Half-Life texture WADs (WAD2/WAD3 magic, the "Wad2"
    // descriptor). The registry's first-claim-wins extension map routes every
    // ".wad" to one of them, so the other's own output is mis-detected and its
    // reader rejects the foreign magic. Disambiguate by the 4-byte magic.
    if (singleExt == ".wad") {
      var wad = DetectWadByMagic(path);
      if (wad != Format.Unknown)
        return wad;
    }

    // The ".dsk" extension is shared by several disk-image filesystems (AppleDOS,
    // CP/M, Amstrad CPC). AppleDOS claims it first and has no magic, so a CPC DSK
    // image (which DOES carry a strong "MV - CPC"/"EXTENDED" magic) is routed to
    // the AppleDOS reader, which rejects it. Honor the CPC magic when present.
    if (singleExt == ".dsk") {
      var cpc = DetectCpcDskByMagic(path);
      if (cpc != Format.Unknown)
        return cpc;
    }

    // ".pak" is Quake's PACK archive and Unreal's package. Quake's magic is the
    // leading "PACK"; Unreal's sits in the footer, so a leading-bytes check can
    // never see it and every Unreal pak was routed to the Quake reader.
    if (singleExt == ".pak") {
      var pak = DetectPakByMagic(path);
      if (pak != Format.Unknown)
        return pak;
    }

    // ".vib" is both a VMware installation bundle (an AR archive) and a Veeam
    // incremental backup. Only one of the two says what it is up front.
    if (singleExt == ".vib") {
      var vib = DetectVibByMagic(path);
      if (vib != Format.Unknown)
        return vib;
    }

    // The ".arc" extension is shared by the legacy SEA ARC format (every entry
    // header starts with the 0x1A magic byte, the "Arc" descriptor) and FreeArc
    // (magic "ArC\x01", the "FreeArc" descriptor). The first-claim-wins map routes
    // every ".arc" to the legacy reader, which rejects FreeArc's own output.
    // Disambiguate by the leading bytes.
    if (singleExt == ".arc") {
      var arc = DetectArcByMagic(path);
      if (arc != Format.Unknown)
        return arc;
    }

    // Single extension lookup from registry
    // An extension claimed by more than one descriptor is settled by the
    // content, among those claimants only: the map below is first-claim-wins,
    // which routes the file to whichever descriptor the registry happened to
    // enumerate first. Restricting the question to the claimants keeps it away
    // from formats that legitimately share their bytes with another — a
    // .tar.gz is gzip inside, and must stay TarGz.
    if (!string.IsNullOrEmpty(singleExt)
        && FormatDetector._extToFormats!.TryGetValue(singleExt, out var claimants)
        && claimants.Count > 1) {
      var chosen = ResolveSharedExtension(path, claimants);
      if (chosen != Format.Unknown) return chosen;
    }

    if (!string.IsNullOrEmpty(singleExt) && FormatDetector._extToFormat!.TryGetValue(singleExt, out var format))
      return format;

    return Format.Unknown;
  }

  private static Format DetectArOrDeb(string lower)
    => lower.EndsWith(".deb") ? Format.Deb : Format.Ar;

  /// <summary>
  ///   Resolves a ".dsk" file to CpcDsk when the leading bytes carry the Amstrad
  ///   CPC "MV - CPC" or "EXTENDED" magic; otherwise returns <see cref="Format.Unknown"/>
  ///   so the caller falls back to the registry extension map (AppleDOS default).
  /// </summary>
  private static Format DetectCpcDskByMagic(string path) {
    try {
      if (!File.Exists(path)) return Format.Unknown;
      using var fs = File.OpenRead(path);
      Span<byte> head = stackalloc byte[8];
      if (fs.Read(head) < 8) return Format.Unknown;
      if (head.StartsWith("MV - CPC"u8) || head.SequenceEqual("EXTENDED"u8))
        return Format.CpcDsk;
    } catch {
      /* ignore detection failure */
    }
    return Format.Unknown;
  }

  /// <summary>
  ///   Resolves a ".arc" file to FreeArc (magic "ArC\x01") or the legacy SEA ARC
  ///   format by reading the leading bytes. Returns <see cref="Format.Unknown"/>
  ///   when unreadable so the caller falls back to the registry extension map.
  /// </summary>
  /// <summary>
  /// Tells Quake's PACK archive from an Unreal package. Quake announces itself in
  /// the first four bytes; Unreal keeps its magic in the footer, ahead of the
  /// trailing index offset and length, so the tail is where it has to be read.
  /// </summary>
  private static Format DetectPakByMagic(string path) {
    try {
      if (!File.Exists(path)) return Format.Unknown;
      using var fs = File.OpenRead(path);
      Span<byte> magic = stackalloc byte[4];
      if (fs.Length >= 4) {
        fs.ReadExactly(magic);
        if (magic[0] == 'P' && magic[1] == 'A' && magic[2] == 'C' && magic[3] == 'K')
          return Format.Pak;
      }

      // The footer is 44 bytes for the versions that keep the magic at its front;
      // later revisions prepend fields, so scan the tail rather than fix an offset.
      var tail = (int)Math.Min(fs.Length, 256);
      if (tail < 4) return Format.Unknown;
      var buffer = new byte[tail];
      fs.Position = fs.Length - tail;
      fs.ReadExactly(buffer);
      for (var i = 0; i + 4 <= tail; ++i)
        if (BinaryPrimitives.ReadUInt32LittleEndian(buffer.AsSpan(i, 4)) == 0x5A6F12E1)
          return Format.UnrealPak;
    } catch {
      /* ignore detection failure */
    }
    return Format.Unknown;
  }

  /// <summary>
  /// Tells a VMware installation bundle from a Veeam incremental backup. The
  /// bundle is an AR archive and says so in its first eight bytes.
  /// </summary>
  private static Format DetectVibByMagic(string path) {
    try {
      if (!File.Exists(path)) return Format.Unknown;
      using var fs = File.OpenRead(path);
      if (fs.Length < 8) return Format.Unknown;
      Span<byte> magic = stackalloc byte[8];
      fs.ReadExactly(magic);
      if (magic.SequenceEqual("!<arch>\n"u8))
        return Format.Vib;
    } catch {
      /* ignore detection failure */
    }
    return Format.Unknown;
  }

  private static Format DetectArcByMagic(string path) {
    try {
      if (!File.Exists(path)) return Format.Unknown;
      using var fs = File.OpenRead(path);
      Span<byte> magic = stackalloc byte[4];
      if (fs.Read(magic) < 4) return Format.Unknown;
      if (magic[0] == 'A' && magic[1] == 'r' && magic[2] == 'C' && magic[3] == 0x01)
        return Format.FreeArc;
      if (magic[0] == 0x1A)
        return Format.Arc;
    } catch {
      /* ignore detection failure */
    }
    return Format.Unknown;
  }

  /// <summary>
  ///   Resolves a ".wad" file to either the Doom WAD descriptor (IWAD/PWAD magic)
  ///   or the Quake/Half-Life WAD2/WAD3 descriptor by reading the 4-byte magic.
  ///   Returns <see cref="Format.Unknown"/> when the file is missing/unreadable so
  ///   the caller falls back to the registry extension map.
  /// </summary>
  private static Format DetectWadByMagic(string path) {
    try {
      if (!File.Exists(path)) return Format.Unknown;
      using var fs = File.OpenRead(path);
      Span<byte> magic = stackalloc byte[4];
      if (fs.Read(magic) < 4) return Format.Unknown;
      if (magic[0] == 'W' && magic[1] == 'A' && magic[2] == 'D'
          && (magic[3] == '2' || magic[3] == '3'))
        return Format.Wad2;
      if ((magic[0] == 'I' || magic[0] == 'P')
          && magic[1] == 'W' && magic[2] == 'A' && magic[3] == 'D')
        return Format.Wad;
    } catch {
      /* ignore detection failure */
    }
    return Format.Unknown;
  }

  private static Format DetectInstaller(string path) {
    try {
      using var fs = File.OpenRead(path);
      var buf = new byte[2];
      var isPe = fs.Read(buf, 0, 2) >= 2 && buf[0] == 'M' && buf[1] == 'Z';

      // NSIS/InnoSetup markers can live anywhere in the file (our own stub-less
      // NSIS writer puts the "NullsoftInst" signature in a leading overlay
      // header, not a PE overlay), so scan the whole file when it is small and
      // the tail otherwise — independent of the MZ check, so a stub-less
      // installer image still re-detects as its own format.
      var scanLen = (int)Math.Min(fs.Length, 65536L);
      if (scanLen > 0) {
        fs.Seek(fs.Length <= 65536L ? 0 : -65536L,
          fs.Length <= 65536L ? SeekOrigin.Begin : SeekOrigin.End);
        var tail = new byte[scanLen];
        var bytesRead = fs.Read(tail, 0, tail.Length);
        var tailSpan = tail.AsSpan(0, bytesRead);
        if (ContainsBytes(tailSpan, "NullsoftInst"u8)) return Format.Nsis;
        if (ContainsBytes(tailSpan, "Inno Setup"u8)) return Format.InnoSetup;
        // PyInstaller "onefile" build: the CArchive MEI cookie sits near EOF,
        // after the PE image (and before any appended Authenticode signature).
        if (ContainsBytes(tailSpan, PyInstallerCookie)) return Format.PyInstaller;
        // BitRock/InstallBuilder: end magic, or compressor id + mk4vfs schema.
        if (ContainsBytes(tailSpan, "mFC3acAOJrQinu5a"u8)
            || (ContainsBytes(tailSpan, "bitrock-lzma"u8)
                && ContainsBytes(tailSpan, "dirs[name:S,parent:I"u8)))
          return Format.BitRock;
      }

      // Beyond the installer-marker scan, a non-PE file is not an installer.
      if (!isPe)
        return Format.Unknown;

      // Check for our own SFX trailer (SFX! magic at end)
      if (fs.Length >= 12) {
        fs.Seek(-4, SeekOrigin.End);
        Span<byte> magic = stackalloc byte[4];
        fs.ReadExactly(magic);
        if (magic[0] == 'S' && magic[1] == 'F' && magic[2] == 'X' && magic[3] == '!')
          return Format.Sfx;
      }

      // Check for third-party SFX: scan PE overlay for embedded archive
      var sfxInfo = PeOverlay.DetectEmbeddedArchive(path);
      if (sfxInfo != null)
        return Format.Sfx;
    } catch {
      /* ignore detection failure */
    }

    // Plain PE executable with no installer signature — surface its embedded resources
    // (icons, version info, manifest, string tables) via the PeResources descriptor.
    return Format.PeResources;
  }

  private static bool ContainsBytes(ReadOnlySpan<byte> haystack, ReadOnlySpan<byte> needle)
    => haystack.IndexOf(needle) >= 0;

  /// <summary>The 8-byte PyInstaller CArchive magic cookie (MEI + version bytes).</summary>
  private static readonly byte[] PyInstallerCookie =
    [(byte)'M', (byte)'E', (byte)'I', 0x0C, 0x0B, 0x0A, 0x0B, 0x0E];

  // ── Magic byte detection ─────────────────────────────────────────
  // Most signatures come from the registry. A few formats need special
  // multi-offset or heuristic logic that can't be expressed as simple
  // byte patterns, so those are handled explicitly after the registry scan.

  public static Format DetectByMagic(ReadOnlySpan<byte> header) {
    if (header.Length < 4) return Format.Unknown;

    EnsureRegistryMapped();

    // Scan the whole registry and pick the highest-confidence match. Earlier this
    // loop returned on the first hit, which let a low-confidence descriptor
    // (e.g. AndroidBundle's 0.15 PK signature, intentionally placed there so
    // Zip's 0.95 would win on extensionless inputs) defeat a later higher-confidence
    // match simply because the registry enumerated it first.
    Format best = Format.Unknown;
    var bestConfidence = 0.0;
    foreach (var desc in Reg.All) {
      if (!FormatDetector._idToFormat!.TryGetValue(desc.Id, out var f))
        continue;

      foreach (var sig in desc.MagicSignatures) {
        if (!MatchesMagic(header, sig)) continue;
        if (sig.Confidence > bestConfidence) {
          bestConfidence = sig.Confidence;
          best = f;
        }
      }
    }
    if (best != Format.Unknown) return best;

    // ── Special heuristic detections not expressible as simple magic ──

    // RefPack/QFS: 0x10 0xFB or at offset 4 (with compressed size prefix)
    if (header.Length >= 5 && (header[0] & 0xFE) == 0x10 && header[1] == 0xFB)
      return Format.RefPack;
    if (header.Length >= 9 && (header[4] & 0xFE) == 0x10 && header[5] == 0xFB)
      return Format.RefPack;

    // LZMA "alone" header: properties byte, 4-byte dict size LE, 8-byte size LE.
    if (IsLzmaAloneHeader(header))
      return Format.Lzma;

    // TAR: "ustar" at offset 257
    if (header.Length >= 263
      && header[257] == 'u'
      && header[258] == 's'
      && header[259] == 't'
      && header[260] == 'a'
      && header[261] == 'r')
      return Format.Tar;

    // FAT has no fixed magic — it is identified by its BIOS Parameter Block.
    // Checked last so any descriptor with a real signature wins first; NTFS and
    // exFAT share the same BPB shape but carry "NTFS    "/"EXFAT   " at offset 3
    // and are therefore already matched above.
    if (IsFatBootSector(header))
      return Format.Fat;

    return Format.Unknown;
  }

  /// <summary>
  ///   Validates an LZMA "alone" (.lzma) header: a properties byte, a 32-bit
  ///   little-endian dictionary size and a 64-bit little-endian uncompressed size.
  ///   <para>
  ///   The format carries no magic, so every field has to be checked or the probe
  ///   turns into a catch-all. In particular the dictionary size must be one of the
  ///   sizes an encoder actually emits (2^n, or 2^n + 2^(n-1) as used by xz/lzma):
  ///   without that, any unrecognized file whose first byte happens to be below
  ///   0xE1 is claimed as LZMA — which is how BMP, PCX, PGM and PPM were being
  ///   mis-identified.
  ///   </para>
  /// </summary>
  private static bool IsLzmaAloneHeader(ReadOnlySpan<byte> header) {
    if (header.Length < 13) return false;

    // props = (pb * 5 + lp) * 9 + lc, so anything at or above 9*5*5 is invalid.
    if (header[0] >= 225) return false;

    var dictSize = (uint)(header[1] | (header[2] << 8) | (header[3] << 16) | (header[4] << 24));

    // Minimum dictionary is 4 KiB; the reference encoder caps at 1 GiB.
    if (dictSize < (1u << 12) || dictSize > (1u << 30)) return false;

    // Accept only 2^n and 2^n + 2^(n-1) — the two shapes real encoders write.
    var isPowerOfTwo = (dictSize & (dictSize - 1)) == 0;
    var withoutTopBit = dictSize & (dictSize - 1);
    var isOneAndAHalf = withoutTopBit != 0 && (withoutTopBit & (withoutTopBit - 1)) == 0
                        && withoutTopBit == (dictSize & ~withoutTopBit) >> 1;
    if (!isPowerOfTwo && !isOneAndAHalf) return false;

    // Uncompressed size: either the "unknown" sentinel or a plausible length.
    var uncompressed = BinaryPrimitives.ReadUInt64LittleEndian(header.Slice(5, 8));
    return uncompressed == ulong.MaxValue || uncompressed < (1UL << 56);
  }

  /// <summary>
  ///   Conservative BIOS Parameter Block check for FAT12/16/32 volumes.
  ///   Every field must be one of the small set of legal values, so a random
  ///   sector that merely happens to end in 0x55 0xAA (an MBR, for instance) is
  ///   rejected.
  /// </summary>
  private static bool IsFatBootSector(ReadOnlySpan<byte> header) {
    if (header.Length < 512) return false;

    // Boot signature.
    if (header[510] != 0x55 || header[511] != 0xAA) return false;

    // Jump instruction: short jump (EB xx 90) or near jump (E9 xx xx).
    if (header[0] != 0xEB && header[0] != 0xE9) return false;

    // Bytes per sector: a power of two in 512..4096.
    var bytesPerSector = header[11] | (header[12] << 8);
    if (bytesPerSector is not (512 or 1024 or 2048 or 4096)) return false;

    // Sectors per cluster: a power of two in 1..128.
    var sectorsPerCluster = header[13];
    if (sectorsPerCluster == 0 || (sectorsPerCluster & (sectorsPerCluster - 1)) != 0 || sectorsPerCluster > 128)
      return false;

    // Reserved sector count is never zero, and there are always 1 or 2 FATs.
    var reservedSectors = header[14] | (header[15] << 8);
    if (reservedSectors == 0) return false;
    if (header[16] is not (1 or 2)) return false;

    return true;
  }

  private static bool MatchesMagic(ReadOnlySpan<byte> header, MagicSignature sig) {
    if (header.Length < sig.Offset + sig.Bytes.Length) return false;

    var slice = header.Slice(sig.Offset, sig.Bytes.Length);
    if (sig.Mask != null) {
      for (var i = 0; i < sig.Bytes.Length; i++)
        if ((slice[i] & sig.Mask[i]) != (sig.Bytes[i] & sig.Mask[i]))
          return false;

      return true;
    }

    return slice.SequenceEqual(sig.Bytes);
  }

  // ── Full detection (extension + magic fallback) ──────────────────

  public static Format Detect(string path) {
    var byExt = DetectByExtension(path);
    if (byExt != Format.Unknown) return byExt;

    return DetectByMagicFromFile(path);
  }

  /// <summary>
  /// Picks the claimant of a shared extension whose own magic matches the file,
  /// preferring the most confident. Returns <see cref="Format.Unknown" /> when
  /// none of them recognises the bytes, leaving the caller's first-claim-wins
  /// answer in place.
  /// </summary>
  private static Format ResolveSharedExtension(string path, List<Format> claimants) {
    var header = ReadHeader(path);
    if (header.Length == 0) return Format.Unknown;

    var best = Format.Unknown;
    var bestConfidence = 0.0;
    foreach (var candidate in claimants) {
      if (!FormatDetector._formatToDesc!.TryGetValue(candidate, out var desc)) continue;
      foreach (var sig in desc.MagicSignatures) {
        if (!MatchesMagic(header, sig)) continue;
        if (sig.Confidence <= bestConfidence) continue;
        bestConfidence = sig.Confidence;
        best = candidate;
      }
    }
    return best;
  }

  /// <summary>Reads as much of the file as the deepest registered signature needs.</summary>
  private static byte[] ReadHeader(string path) {
    EnsureRegistryMapped();
    try {
      if (!File.Exists(path)) return [];
      using var stream = File.OpenRead(path);
      var want = (int)Math.Min(Math.Max(FormatDetector._maxMagicExtent, FastProbeBytes), stream.Length);
      if (want <= 0) return [];
      var buffer = new byte[want];
      var read = stream.ReadAtLeast(buffer, want, throwOnEndOfStream: false);
      return read == want ? buffer : buffer[..read];
    } catch {
      return [];
    }
  }

  /// <summary>
  ///   For SFX files, returns the embedded archive's format and offset.
  ///   Handles both our own SFX format (SFX! trailer) and third-party SFX (PE overlay scan).
  ///   Returns null if the file is not an SFX or contains no detectable archive.
  /// </summary>
  public static (Format ArchiveFormat, long Offset, long Length)? GetSfxArchiveInfo(string path) {
    // First check our own SFX trailer
    var ownSfx = SfxBuilder.ReadTrailer(path);
    if (ownSfx != null)
      return (ownSfx.Value.Format, ownSfx.Value.Offset, ownSfx.Value.Length);

    // Then check for third-party SFX via PE overlay
    var peInfo = PeOverlay.DetectEmbeddedArchive(path);
    if (peInfo != null) {
      var fileLen = new FileInfo(path).Length;
      return (peInfo.Value.Format, peInfo.Value.Offset, fileLen - peInfo.Value.Offset);
    }

    return null;
  }

  // ── Default extension (derived from registry) ────────────────────

  public static string GetDefaultExtension(Format format) {
    var desc = GetDesc(format);
    if (desc != null) return desc.DefaultExtension;

    return format switch {
      Format.Sfx => ".exe",
      Format.Iso => ".iso",
      Format.Udf => ".udf",
      _ => ""
    };
  }

  // ── Extension set for stream formats (used by StripCompressionExtension) ──

  public static bool IsStreamExtension(string ext) {
    EnsureRegistryMapped();
    if (string.IsNullOrEmpty(ext)) return false;

    // Check single extensions of all stream/wrapper formats
    foreach (var desc in Reg.All) {
      if (desc.Category is not (FormatCategory.Stream or FormatCategory.Wrapper)) continue;

      foreach (var e in desc.Extensions)
        if (e.Equals(ext, StringComparison.OrdinalIgnoreCase))
          return true;
    }

    return false;
  }
}
